    // HP can be from 0 to some upper bound
    // ATK can be from 0 to some upper bound
    // DEF can be from 0 to some upper bound

    // We need to find the minimum cost
    // Let's iterate over possible additional ATK and DEF, and compute required HP

    // Additional ATK: 0 to 200 (since initial ATK is at most 100, and we might need to go up)
    // Additional DEF: 0 to 200
    // Additional HP: computed based on the battle

    for (int addATK = 0; addATK <= 200; addATK++) {
        for (int addDEF = 0; addDEF <= 200; addDEF++) {
            int newATK = ATKY + addATK;
            int newDEF = DEFY + addDEF;

            // Damage Yang deals to monster per second
            int dmgToMonster = max(0, newATK - DEFM);

            // If Yang can't deal any damage, he can't win
            if (dmgToMonster <= 0) {
                continue;
            }

            // Number of seconds to kill the monster
            int secondsToKill = (HPM + dmgToMonster - 1) / dmgToMonster;

            // Damage monster deals to Yang per second
            int dmgToYang = max(0, ATKM - newDEF);

            // If monster can't deal any damage, Yang needs at least 1 HP
            int requiredHP;
