                requiredHP = 1;
            } else {
                // Yang needs to survive secondsToKill seconds
                // After secondsToKill seconds, Yang's HP must be > 0
                // Yang's HP after secondsToKill seconds = HP - secondsToKill * dmgToYang > 0
                // So HP > secondsToKill * dmgToYang
                // Minimum HP = secondsToKill * dmgToYang + 1
