    int HPY, ATKY, DEFY;
    int HPM, ATKM, DEFM;
    int h, a, d;

    if (!(cin >> HPY >> ATKY >> DEFY)) return 0;
    if (!(cin >> HPM >> ATKM >> DEFM)) return 0;
    if (!(cin >> h >> a >> d)) return 0;

    int minCost = INT_MAX;

    // We iterate over the possible number of ATK points to buy (0 to 100)
    // and DEF points to buy (0 to 100).
    // The input constraints say all numbers are between 1 and 100.
    // It's safe to assume we don't need to buy more than 100 extra ATK or DEF.
    // Why? 
    // If we buy enough ATK such that ATKY + i > DEFM, we deal damage.
    // If we buy enough DEF such that DEFY + j > ATKM, we take 0 damage.
    // Since ATKM and DEFM are at most 100, buying up to 100 extra is sufficient to cover any scenario where damage becomes 0 or positive.
    // Actually, if ATKM is 100 and DEFY is 1, we might need up to 100 DEF to make damage 0.
    // If DEFM is 100 and ATKY is 1, we might need up to 100 ATK to make damage 1.
    // So iterating 0..100 for both is safe.

    for (int addATK = 0; addATK <= 100; ++addATK) {
        int newATK = ATKY + addATK;
        int damageToMonster = max(0, newATK - DEFM);

        // If we can't deal any damage, we can't win (unless monster HP is already <=0, but HPM >= 1)
        if (damageToMonster == 0) {
            continue;
        }

        // Calculate the number of turns needed to kill the monster
        // turns = ceil(HPM / damageToMonster)
        int turns = (HPM + damageToMonster - 1) / damageToMonster;

        for (int addDEF = 0; addDEF <= 100; ++addDEF) {
            int newDEF = DEFY + addDEF;
            int damageToYang = max(0, ATKM - newDEF);

            // If damageToYang is 0, Yang takes no damage.
            // Otherwise, Yang needs to survive 'turns' hits.
            // Yang's HP must be > damageToYang * (turns - 1) ? 
            // Let's check the condition:
            // After 'turns' seconds, monster HP <= 0.
            // Yang's HP decreases by damageToYang every second.
            // After 'turns' seconds, Yang's HP = HPY + addHP - damageToYang * turns.
            // We need Yang's HP > 0.
            // So HPY + addHP > damageToYang * turns.
            // addHP > damageToYang * turns - HPY.
            // Since addHP must be an integer >= 0,
            // addHP >= max(0, damageToYang * turns - HPY + 1).

            int requiredHP = 0;
            if (damageToYang > 0) {
                // Yang must have HP > damageToYang * turns
                // So HP >= damageToYang * turns + 1
                requiredHP = damageToYang * turns + 1;
            } else {
                // If damage is 0, Yang just needs HP > 0, which is always true since initial HP >= 1.
                // But wait, if damage is 0, Yang's HP doesn't decrease.
                // So any HP >= 1 is fine.
                requiredHP = 1;
            }

            int addHP = max(0, requiredHP - HPY);

            int cost = addATK * a + addDEF * d + addHP * h;

            if (cost < minCost) {
                minCost = cost;
            }
        }
    }

    // It is possible that no combination works? 
    // But we can always buy enough ATK to deal 1 damage per turn, and enough DEF to take 0 damage.
    // So a solution always exists.

    cout << minCost << endl;

    return 0;
}

