#include <iostream>
#include <algorithm>
#include <climits>

using namespace std;

int main() {
    int HPY, ATKY, DEFY;
    int HPM, ATKM, DEFM;
    int h, a, d;

    if (!(cin >> HPY >> ATKY >> DEFY)) return 0;
    if (!(cin >> HPM >> ATKM >> DEFM)) return 0;
    if (!(cin >> h >> a >> d)) return 0;

    int min_cost = INT_MAX;

    // We need to determine the range of additional ATK and DEF to buy.
    // The maximum useful ATK is ATKM + DEFM (to deal at least 1 damage).
    // Any more ATK doesn't reduce the number of turns needed if we already deal 1 damage, 
    // but it might reduce turns if we deal more. However, since HPM <= 100, 
    // the number of turns needed is at most HPM if damage is 1.
    // So max useful ATK is ATKM + DEFM.
    // Similarly, max useful DEF is ATKM (to take 0 damage).

    // Let's iterate over possible additional ATK (da) and additional DEF (dd).
    // da can range from 0 to ATKM + DEFM - ATKY (if positive).
    // Actually, let's just iterate up to a reasonable bound.
    // Since HPM <= 100, the number of turns is at most 100 if damage >= 1.
    // If damage is 0, we can't win.
    // Max damage needed to kill in 1 turn is HPM. So max ATK needed is DEFM + HPM.
    // But since ATKM and DEFM are <= 100, DEFM + HPM <= 200.
    // So ATKY + da <= 200 is a safe upper bound for ATK.
    // Similarly, to take 0 damage, DEFY + dd >= ATKM. ATKM <= 100.
    // So DEFY + dd <= 100 is a safe upper bound for DEF.

    // Let's set upper bounds.
    // Max ATK to consider: DEFM + HPM (to kill in 1 hit) or just a bit more.
    // Actually, if we deal more damage, we need fewer turns.
    // The number of turns T is ceil(HPM / damage).
    // damage = max(0, ATKY + da - DEFM).
    // If damage <= 0, we can't win.
    // Max useful da: such that ATKY + da - DEFM >= HPM (kill in 1 turn).
    // So da_max = max(0, DEFM + HPM - ATKY).

    // Max useful dd: such that DEFY + dd >= ATKM (take 0 damage).
    // So dd_max = max(0, ATKM - DEFY).

    int da_max = max(0, DEFM + HPM - ATKY);
    int dd_max = max(0, ATKM - DEFY);

    for (int da = 0; da <= da_max; ++da) {
        for (int dd = 0; dd <= dd_max; ++dd) {
            int new_ATK = ATKY + da;
            int new_DEF = DEFY + dd;

            int damage_to_monster = max(0, new_ATK - DEFM);
            if (damage_to_monster <= 0) {
                continue; // Can't kill the monster
            }

            // Calculate number of turns needed to kill the monster
            // Turns = ceil(HPM / damage_to_monster)
            int turns = (HPM + damage_to_monster - 1) / damage_to_monster;

            // Calculate damage taken per turn
            int damage_to_yang = max(0, ATKM - new_DEF);

            // Total damage taken by Yang
            int total_damage_taken = turns * damage_to_yang;

            // Yang needs HPY + dh > total_damage_taken
            // So HPY + dh >= total_damage_taken + 1
            // dh >= total_damage_taken + 1 - HPY
            int dh_needed = total_damage_taken + 1 - HPY;
            if (dh_needed < 0) dh_needed = 0;

            int cost = da * a + dd * d + dh_needed * h;

            if (cost < min_cost) {
                min_cost = cost;
            }
        }
    }

    // It's possible that the bounds were too tight? 
    // Let's double check.
    // If da_max is calculated as DEFM + HPM - ATKY, then damage = HPM, turns = 1.
    // If we buy more ATK, turns is still 1, but cost increases. So no need.
    // If dd_max is calculated as ATKM - DEFY, then damage_to_yang = 0.
    // If we buy more DEF, cost increases. So no need.

    // What if the optimal solution requires buying more DEF than ATKM - DEFY?
    // No, because if DEFY + dd >= ATKM, damage is 0. More DEF doesn't help.
    // What if the optimal solution requires buying more ATK than DEFM + HPM - ATKY?
    // No, because if damage >= HPM, turns is 1. More ATK doesn't reduce turns below 1.

    // However, what if the initial stats are such that we need to buy a lot of HP?
    // The loop covers all necessary da and dd. For each, we calculate the minimal dh.

    // Edge case: What if min_cost is still INT_MAX?
    // This would happen if we can't win even with max ATK and DEF?
    // But with max ATK (damage >= HPM) and max DEF (damage taken = 0), 
    // turns = 1, total_damage = 0, dh_needed = 1 - HPY.
    // If HPY >= 1, dh_needed <= 0, so dh = 0.
    // So we can always win by buying enough ATK and DEF.
    // Since all inputs are >= 1, this should be fine.

    cout << min_cost << endl;

    return 0;
}

