#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int HPY, ATKY, DEFY;
    int HPM, ATKM, DEFM;
    int h, a, d;

    cin >> HPY >> ATKY >> DEFY;
    cin >> HPM >> ATKM >> DEFM;
    cin >> h >> a >> d;

    int minCost = 1000000000; // large number

    // We need to find the minimum cost to win.
    // Yang wins if:
    // 1. Yang's total HP > 0 after the battle
    // 2. Monster's HP <= 0 after the battle
    // 3. The number of turns Yang needs to kill the monster is less than or equal to the number of turns Yang can survive
    //    Actually, both attack simultaneously. So in each turn:
    //    - Monster loses max(0, ATKY - DEFM) HP
    //    - Yang loses max(0, ATKM - DEFY) HP
    //    Battle ends when either monster HP <= 0 or Yang HP <= 0.
    //    Yang wins if monster HP <= 0 AND Yang HP > 0 at the same time.

    // Let's denote:
    // newATK = ATKY + addATK
    // newDEF = DEFY + addDEF
    // newHP = HPY + addHP

    // Damage Yang deals per turn: dmgY = max(0, newATK - DEFM)
    // Damage Monster deals per turn: dmgM = max(0, ATKM - newDEF)

    // If dmgY <= 0, Yang can never kill the monster (unless HPM <= 0, but HPM >= 1)
    // If dmgM >= newHP, Yang dies in the first turn (or before killing monster)

    // Number of turns to kill monster: turnsToKill = ceil(HPM / dmgY) if dmgY > 0
    // Number of turns Yang can survive: turnsToSurvive = floor((newHP - 1) / dmgM) if dmgM > 0, else infinity

    // Yang wins if:
    // - dmgY > 0
    // - turnsToKill <= turnsToSurvive
    //   i.e., ceil(HPM / dmgY) <= floor((newHP - 1) / dmgM) if dmgM > 0
    //   or dmgY > 0 and dmgM == 0 (Yang never takes damage)

    // Since all values are between 1 and 100, we can brute force.
    // Max HP we might need: if dmgM = 1, and HPM = 100, dmgY = 1, then turnsToKill = 100, so newHP needs to be at least 100.
    // Actually, worst case: HPM=100, dmgY=1, ATKM=100, newDEF=1, so dmgM=99.
    // turnsToKill = 100. turnsToSurvive = floor((newHP-1)/99). We need 100 <= floor((newHP-1)/99)
    // So newHP-1 >= 99*100 = 9900, newHP >= 9901.
    // But wait, HPY is at most 100, so addHP could be up to ~9900.
    // However, the problem says all input numbers are between 1 and 100.
    // Let's think about the maximum possible addHP needed.
    // Actually, let's just iterate over reasonable ranges.
    // Since prices are at most 100, and we want minimum cost, we can bound the search.

    // Let's try addATK from 0 to 100 (since ATKM and DEFM are at most 100, max useful ATK is DEFM + HPM, but HPM <= 100, so ATK up to 200 might be needed? No, dmgY just needs to be > 0. But higher ATK means fewer turns. Let's go up to 200 to be safe.)
    // Actually, let's think: if ATKY is already high enough, we don't need more. Max useful addATK: we want dmgY to be at least HPM (to kill in 1 turn). So newATK >= DEFM + HPM. DEFM <= 100, HPM <= 100, so newATK up to 200. ATKY >= 1, so addATK up to 199.
    // Similarly for DEF: we want dmgM to be 0, so newDEF >= ATKM. ATKM <= 100, DEFY >= 1, so addDEF up to 99.
    // For HP: as calculated, could be large. But let's bound it.
    // If dmgM = 1 (minimum positive damage), and turnsToKill is at most HPM (when dmgY=1), so turnsToKill <= 100.
    // We need floor((newHP-1)/1) >= 100, so newHP-1 >= 100, newHP >= 101.
    // Wait, if dmgM is larger, we need more HP.
    // Max dmgM = ATKM - newDEF. If newDEF = 1 (minimum), dmgM = ATKM - 1 <= 99.
    // Max turnsToKill = HPM (when dmgY = 1).
    // So we need floor((newHP-1)/99) >= 100, so newHP-1 >= 9900, newHP >= 9901.
    // So addHP could be up to 9901 - 1 = 9900.
    // That's a lot to iterate. But we can be smarter.

    // Alternative approach: iterate over addATK and addDEF, and for each, calculate the minimum addHP needed.
    // For given addATK and addDEF:
    //   newATK = ATKY + addATK
    //   newDEF = DEFY + addDEF
    //   dmgY = max(0, newATK - DEFM)
    //   dmgM = max(0, ATKM - newDEF)
    //   
    //   If dmgY == 0: cannot win, skip.
    //   If dmgM == 0: Yang takes no damage, so any HP > 0 works. Since HPY >= 1, addHP = 0.
    //   Else:
    //     turnsToKill = ceil(HPM / dmgY) = (HPM + dmgY - 1) / dmgY
    //     We need Yang to survive at least turnsToKill turns.
    //     Yang's HP after turnsToKill turns: newHP - dmgM * turnsToKill > 0
    //     So newHP > dmgM * turnsToKill
    //     newHP >= dmgM * turnsToKill + 1
    //     addHP = max(0, dmgM * turnsToKill + 1 - HPY)
    //   
    //   Cost = addATK * a + addDEF * d + addHP * h
    //   Update minCost.

    // Range for addATK: 0 to (DEFM + HPM - ATKY) if positive, but let's just go 0 to 200.
    // Range for addDEF: 0 to (ATKM - DEFY) if positive, but let's go 0 to 100.

    for (int addATK = 0; addATK <= 200; addATK++) {
        for (int addDEF = 0; addDEF <= 100; addDEF++) {
            int newATK = ATKY + addATK;
            int newDEF = DEFY + addDEF;
            int dmgY = max(0, newATK - DEFM);
            int dmgM = max(0, ATKM - newDEF);

            if (dmgY == 0) {
                continue; // Can't kill monster
            }

            int addHP = 0;
            if (dmgM == 0) {
                addHP = 0; // No damage taken, current HP is enough (HPY >= 1)
            } else {
                int turnsToKill = (HPM + dmgY - 1) / dmgY; // ceil(HPM / dmgY)
                int minHPNeeded = dmgM * turnsToKill + 1;
                if (minHPNeeded > HPY) {
                    addHP = minHPNeeded - HPY;
                }
            }

            int cost = addATK * a + addDEF * d + addHP * h;
            if (cost < minCost) {
                minCost = cost;
            }
        }
    }

    cout << minCost << endl;

    return 0;
}
